using static StrataLint.Scribe.DefinitionDsl;
namespace StrataLint.Scribe.Blueprint.D5.S3.Arith.FibonacciAtomic.Observer;
internal sealed class NativeWholeRowServiceDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/Arith/FibonacciAtomic/Observer/NativeWholeRowService.";
    private static DocumentBlock Entry(string n, string title, string prose, DescribeRole role) =>
        Describe.Lean(DescribeId.Create("nativewholerowservice-" + n.Replace("_", "-").ToLowerInvariant()),
            DeclarationHandle.Create(Prefix + n), H(title), StatementSource.WithoutFormula(),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text(prose))), role);
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Native finite whole-row criterion and lawful source fibers", H("NativeWholeRowService"), Blocks(
            Paragraph(Text("NativeWholeRowPlan supplies the exhaustive ground-binding criterion, paid query plans, record reconstruction and their correctness proofs. This module imports that complete API. twoPhaseController, compileService and controller use a single chronological paid reply history and return once. two_phase_execution proves continuous execution; stationary_cell_service combines the criterion, exact record and budget with that execution; stationary_whole_fiber_service extends correctness to every source in the complete retained-row/history fiber. The concrete groundBindingInput application is described in NativeWholeRowPlan with its unconditional all-source, all-epoch scope and formal K0(input) bound. Original serial-update inclusion, U8 and resource optimality remain outside these stationary results.")),
            Entry("compileService", "compileService", "Only common retained inputs and the certified epoch enter preprocessing. The first list acquires all original replies below the fixed depth, and the selected second list probes every genuine ground binding. The program performs one continuous run with one final absorbing return of the complete record. stationary_cell_service proves correctness and the uniform raw budget of this very controller; stationary_whole_fiber_service extends that result to all sources with the same complete old row and literal history. Incomplete transcript lengths and failed cell checks return a fixed common leaf record.", DescribeRole.Definition),
            Entry("controller", "controller", "The selector uses the compiled common program and newly paid chronological replies. No unknown source, subtree, valuation, fiber witness or source identity is a runtime input.", DescribeRole.Definition),
            Entry("two_phase_execution", "two phase execution", "The complete native statement is retained with its exact quantified scope and all premises. Native statement: theorem two_phase_execution {L : Type} (first : List Address) (second : Hist (fun _ : Address => Reply) → List Address) (finish : Hist (fun _ : Address => Reply) → L) (u : Source) : let one := listTrace first u let two := listTrace (second one) u execute readout (twoPhaseController first second finish) (first.length + (second one).length + 1) [] u = some (one ++ two,finish (one ++ two)) ∧ (one ++ two).length = first.length + (second one).length ∧ (one ++ two).map Sigma.fst = first ++ second one", DescribeRole.Theorem),
            Entry("stationary_cell_service", "stationary cell service", "The actual compiled controller terminates on every lawful filling of every feasible admitted cell, returning the entire original literal record with at most K0 raw reads. Native statement: theorem stationary_cell_service {C : LiteralRow} (Q : CutSet) (H : History) (hQ : CutPrefixFree Q) (good : (analyze C Q H).passes = true) (η : Patterns C (requiredDepth Q H)) (feasibleCell : feasible η H = true) (v : Variables η → Source) (legal : Diseq (delta η) v) (N : Nat) : let program := compileService C Q H N let u := evaluate v (wholeTerm η) ∃ fuel trace, execute readout (controller program) fuel [] (substitution^[N] u) = some (trace,literalRecord Q u) ∧ trace.length ≤ K0 C Q H", DescribeRole.Theorem),
            Entry("stationary_whole_fiber_service", "stationary whole fiber service", "The exact native history-cell/source equivalence lifts the controller result to every source in the complete retained-row/history fiber. All old disequalities, repeated class occurrences and absent-cut guards remain present. This stationary execute result does not establish the unpublished original serial-service inclusion or U8. Native statement: theorem stationary_whole_fiber_service (P Q : CutSet) (hP : CutPrefixFree P) (hQ : CutPrefixFree Q) (base : Source) (H : History) (good : (analyze (canonicalRow P base) Q H).passes = true) (N : Nat) (u : Source) (old : canonicalRow P u = canonicalRow P base) (history : NativeDepthPatterns.Consistent H u) : ∃ fuel trace, execute readout (controller (compileService (canonicalRow P base) Q H N)) fuel [] (substitution^[N] u) = some (trace,literalRecord Q u) ∧ trace.length ≤ K0 (canonicalRow P base) Q H", DescribeRole.Theorem))));
}
